create table if not exists public.supplier_events(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id) on delete cascade,event_type text not null,from_value text,to_value text,reason text,metadata jsonb not null default '{}'::jsonb,performed_by uuid references public.profiles(id),created_at timestamptz not null default now());
alter table public.supplier_events enable row level security; create index if not exists idx_supplier_events_supplier_created on public.supplier_events(supplier_id,created_at desc); create unique index if not exists ux_suppliers_code_ci on public.suppliers(lower(supplier_code)) where supplier_code is not null;
alter table public.suppliers drop constraint if exists suppliers_status_check; alter table public.suppliers add constraint suppliers_status_check check(status in('pending','active','inactive','blocked')); alter table public.suppliers drop constraint if exists suppliers_kyc_status_check; alter table public.suppliers add constraint suppliers_kyc_status_check check(kyc_status is null or kyc_status in('pending','approved','expired','rejected')); alter table public.suppliers drop constraint if exists suppliers_rating_check; alter table public.suppliers add constraint suppliers_rating_check check(rating is null or(rating>=0 and rating<=5));
create or replace function public.supplier_current_role() returns text language sql stable security definer set search_path=public as $$select coalesce((select role::text from public.profiles where id=auth.uid() and active=true limit 1),'unknown')$$; create or replace function public.supplier_can_write() returns boolean language sql stable security definer set search_path=public as $$select public.supplier_current_role() in('admin','ceo','manager','dealer','logistics','operations')$$; create or replace function public.supplier_can_control() returns boolean language sql stable security definer set search_path=public as $$select public.supplier_current_role() in('admin','ceo','manager')$$; create or replace function public.supplier_can_control_terms() returns boolean language sql stable security definer set search_path=public as $$select public.supplier_current_role() in('admin','ceo','manager','finance')$$; create or replace function public.supplier_can_rate() returns boolean language sql stable security definer set search_path=public as $$select public.supplier_current_role() in('admin','ceo','manager','dealer','logistics','operations')$$; create or replace function public.supplier_can_delete() returns boolean language sql stable security definer set search_path=public as $$select public.supplier_current_role() in('admin','ceo')$$;
revoke all on function public.supplier_current_role() from public; revoke all on function public.supplier_can_write() from public; revoke all on function public.supplier_can_control() from public; revoke all on function public.supplier_can_control_terms() from public; revoke all on function public.supplier_can_rate() from public; revoke all on function public.supplier_can_delete() from public; grant execute on function public.supplier_current_role() to authenticated,service_role; grant execute on function public.supplier_can_write() to authenticated,service_role; grant execute on function public.supplier_can_control() to authenticated,service_role; grant execute on function public.supplier_can_control_terms() to authenticated,service_role; grant execute on function public.supplier_can_rate() to authenticated,service_role; grant execute on function public.supplier_can_delete() to authenticated,service_role;
alter table public.suppliers enable row level security; drop policy if exists authenticated_insert on public.suppliers; drop policy if exists authenticated_select on public.suppliers; drop policy if exists authenticated_update on public.suppliers; drop policy if exists manager_delete on public.suppliers; drop policy if exists suppliers_read_authenticated on public.suppliers; drop policy if exists suppliers_insert_roles on public.suppliers; drop policy if exists suppliers_update_roles on public.suppliers; create policy suppliers_read_authenticated on public.suppliers for select to authenticated using(true); create policy suppliers_insert_roles on public.suppliers for insert to authenticated with check(public.supplier_can_write()); create policy suppliers_update_roles on public.suppliers for update to authenticated using(public.supplier_can_write()) with check(public.supplier_can_write()); drop policy if exists supplier_events_read_authenticated on public.supplier_events; create policy supplier_events_read_authenticated on public.supplier_events for select to authenticated using(true);
create or replace function public.supplier_create_guard() returns trigger language plpgsql set search_path=public as $$declare v_role text:=public.supplier_current_role(); begin if current_user not in('postgres','service_role') then new.status:='pending';new.kyc_status:='pending';new.rating:=0;new.currency:='AED';new.payment_terms:=null;if v_role='dealer' then new.account_manager_id:=auth.uid();else new.account_manager_id:=null;end if;new.created_by:=auth.uid();end if;return new;end$$; drop trigger if exists trg_supplier_create_guard on public.suppliers; create trigger trg_supplier_create_guard before insert on public.suppliers for each row execute function public.supplier_create_guard();
create or replace function public.supplier_sensitive_update_guard() returns trigger language plpgsql set search_path=public as $$begin if current_user not in('postgres','service_role') and(new.status is distinct from old.status or new.kyc_status is distinct from old.kyc_status or new.currency is distinct from old.currency or new.payment_terms is distinct from old.payment_terms or new.account_manager_id is distinct from old.account_manager_id or new.rating is distinct from old.rating) then raise exception 'Sensitive supplier controls must use controlled supplier workflows.';end if;return new;end$$; drop trigger if exists trg_supplier_sensitive_update_guard on public.suppliers; create trigger trg_supplier_sensitive_update_guard before update on public.suppliers for each row execute function public.supplier_sensitive_update_guard();
create or replace function public.supplier_set_status_v1(p_supplier_id uuid,p_status text,p_reason text default null) returns public.suppliers language plpgsql security definer set search_path=public as $$declare v_row public.suppliers;v_old text;begin if not public.supplier_can_control() then raise exception 'Supplier status control requires manager-level permission.';end if;if p_status not in('pending','active','inactive','blocked') then raise exception 'Invalid supplier status.';end if;if p_status in('inactive','blocked') and length(trim(coalesce(p_reason,'')))<5 then raise exception 'A reason of at least 5 characters is required.';end if;select * into v_row from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;if p_status='active' and coalesce(v_row.kyc_status,'pending')<>'approved' then raise exception 'Supplier cannot be activated until KYC is approved.';end if;v_old:=v_row.status;update public.suppliers set status=p_status,updated_at=now() where id=p_supplier_id returning * into v_row;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,performed_by) values(p_supplier_id,'status_changed',v_old,p_status,nullif(trim(coalesce(p_reason,'')),''),auth.uid());return v_row;end$$;
create or replace function public.supplier_set_kyc_v1(p_supplier_id uuid,p_kyc_status text,p_reason text default null) returns public.suppliers language plpgsql security definer set search_path=public as $$declare v_row public.suppliers;v_old text;begin if not public.supplier_can_control() then raise exception 'KYC control requires manager-level permission.';end if;if p_kyc_status not in('pending','approved','expired','rejected') then raise exception 'Invalid KYC status.';end if;if p_kyc_status in('expired','rejected') and length(trim(coalesce(p_reason,'')))<5 then raise exception 'A reason of at least 5 characters is required.';end if;select * into v_row from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;v_old:=coalesce(v_row.kyc_status,'pending');update public.suppliers set kyc_status=p_kyc_status,updated_at=now() where id=p_supplier_id returning * into v_row;if p_kyc_status in('expired','rejected') and v_row.status='active' then update public.suppliers set status='pending',updated_at=now() where id=p_supplier_id returning * into v_row;end if;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,performed_by) values(p_supplier_id,'kyc_changed',v_old,p_kyc_status,nullif(trim(coalesce(p_reason,'')),''),auth.uid());return v_row;end$$;
create or replace function public.supplier_set_terms_v1(p_supplier_id uuid,p_currency text,p_payment_terms text,p_reason text) returns public.suppliers language plpgsql security definer set search_path=public as $$declare v_row public.suppliers;v_old_currency text;v_old_terms text;v_currency text:=upper(trim(coalesce(p_currency,'')));begin if not public.supplier_can_control_terms() then raise exception 'Supplier commercial terms require finance or manager-level permission.';end if;if v_currency!~'^[A-Z]{3}$' then raise exception 'Currency must be a three-letter ISO code.';end if;if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Commercial terms change reason must contain at least 5 characters.';end if;select * into v_row from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;v_old_currency:=coalesce(v_row.currency,'AED');v_old_terms:=coalesce(v_row.payment_terms,'');update public.suppliers set currency=v_currency,payment_terms=nullif(trim(coalesce(p_payment_terms,'')),''),updated_at=now() where id=p_supplier_id returning * into v_row;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,metadata,performed_by) values(p_supplier_id,'terms_changed',v_old_currency||' | '||v_old_terms,v_currency||' | '||coalesce(trim(p_payment_terms),''),trim(p_reason),jsonb_build_object('old_currency',v_old_currency,'new_currency',v_currency,'old_terms',v_old_terms,'new_terms',nullif(trim(coalesce(p_payment_terms,'')),'')),auth.uid());return v_row;end$$;
create or replace function public.supplier_assign_manager_v1(p_supplier_id uuid,p_manager_id uuid,p_reason text default null) returns public.suppliers language plpgsql security definer set search_path=public as $$declare v_role text:=public.supplier_current_role();v_row public.suppliers;v_old uuid;begin if v_role not in('admin','ceo','manager','dealer') then raise exception 'Supplier ownership assignment is not permitted for this role.';end if;if v_role='dealer' and p_manager_id is distinct from auth.uid() then raise exception 'Dealer users may only assign a supplier to themselves.';end if;if p_manager_id is not null and not exists(select 1 from public.profiles where id=p_manager_id and active=true) then raise exception 'Selected account manager is not an active user.';end if;select * into v_row from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;v_old:=v_row.account_manager_id;update public.suppliers set account_manager_id=p_manager_id,updated_at=now() where id=p_supplier_id returning * into v_row;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,performed_by) values(p_supplier_id,'manager_changed',v_old::text,p_manager_id::text,nullif(trim(coalesce(p_reason,'')),''),auth.uid());return v_row;end$$;
create or replace function public.supplier_set_rating_v1(p_supplier_id uuid,p_rating numeric,p_reason text default null) returns public.suppliers language plpgsql security definer set search_path=public as $$declare v_row public.suppliers;v_old numeric;begin if not public.supplier_can_rate() then raise exception 'Supplier rating is not permitted for this role.';end if;if p_rating<0 or p_rating>5 then raise exception 'Supplier rating must be between 0 and 5.';end if;if p_rating>0 and p_rating<3 and length(trim(coalesce(p_reason,'')))<5 then raise exception 'Low supplier ratings require a reason of at least 5 characters.';end if;select * into v_row from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;v_old:=coalesce(v_row.rating,0);update public.suppliers set rating=p_rating,updated_at=now() where id=p_supplier_id returning * into v_row;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,performed_by) values(p_supplier_id,'rating_changed',v_old::text,p_rating::text,nullif(trim(coalesce(p_reason,'')),''),auth.uid());return v_row;end$$;
grant execute on function public.supplier_set_status_v1(uuid,text,text) to authenticated,service_role;grant execute on function public.supplier_set_kyc_v1(uuid,text,text) to authenticated,service_role;grant execute on function public.supplier_set_terms_v1(uuid,text,text,text) to authenticated,service_role;grant execute on function public.supplier_assign_manager_v1(uuid,uuid,text) to authenticated,service_role;grant execute on function public.supplier_set_rating_v1(uuid,numeric,text) to authenticated,service_role;